  var SOURCE_CSS = "\n:host{\n  --pitch:#075F48; --pitch-d:#054A38; --pitch-t:#E9F3EF;\n  --coal:#06201A; --coal2:#0A2A22; --ink:#0C201A; --ink2:#41544A; --ink3:#71847A; --ink4:#93A39B;\n  --chalk:#F7F6F0; --mist:#EEF4F0; --canvas:#E7ECE8; --paper:#FFFFFF;\n  --volt:#D8F547; --volt-d:#9DAE2C;\n  --amber:#B8860B; --amber-t:#FBF1DD; --red:#B3423A; --red-t:#F7E7E5;\n  --line:rgba(12,32,26,.12); --line2:rgba(12,32,26,.2);\n  --r-sm:10px; --r-md:16px; --r-lg:22px; --r-pill:999px;\n  --mono:'IBM Plex Mono',ui-monospace,monospace;\n  --sans:'Archivo',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;\n  --display:'Anton',Impact,sans-serif;\n  --shadow-1:0 1px 2px rgba(6,32,26,.05),0 8px 20px rgba(6,32,26,.06);\n  --shadow-2:0 18px 44px rgba(6,32,26,.16);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\n:host{background:var(--canvas);font-family:var(--sans);color:var(--ink);-webkit-font-smoothing:antialiased}\na{color:inherit;text-decoration:none}\n\n/* ============================================================\n   SPEC-DOCUMENT CHROME\n   ============================================================ */\n.spec-cover{padding:96px 64px 68px;background:linear-gradient(150deg,var(--coal) 0%,var(--coal2) 58%,#03231c 100%);color:var(--chalk);position:relative;overflow:hidden}\n.spec-cover::before{content:\"\";position:absolute;top:-60px;right:-40px;width:460px;height:460px;background:repeating-linear-gradient(-45deg,var(--pitch) 0 14px,transparent 14px 30px);opacity:.28;-webkit-mask-image:radial-gradient(circle,#000 0%,transparent 72%);mask-image:radial-gradient(circle,#000 0%,transparent 72%)}\n.spec-cover .cover-logo{position:relative;z-index:1;margin-bottom:34px}\n.spec-cover .eyebrow{position:relative;z-index:1;display:block;font-family:var(--mono);font-size:11px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:var(--volt)}\n.spec-cover h1{position:relative;z-index:1;margin:16px 0 0;font-family:var(--display);font-weight:400;text-transform:uppercase;font-size:46px;line-height:1.06}\n.spec-cover p.lede{position:relative;z-index:1;margin:20px 0 0;max-width:760px;font-size:15px;line-height:1.7;color:rgba(247,246,240,.86)}\n.spec-cover .meta-row{position:relative;z-index:1;display:flex;gap:36px;flex-wrap:wrap;margin-top:44px;padding-top:28px;border-top:1px solid rgba(247,246,240,.16)}\n.spec-cover .meta-row small{display:block;font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:rgba(216,245,71,.85)}\n.spec-cover .meta-row b{display:block;margin-top:8px;font-size:14.5px;font-weight:600;color:var(--chalk)}\n.spec-toc{padding:48px 64px;background:#fff;border-bottom:1px solid var(--line)}\n.spec-toc h2{margin:0;font-family:var(--mono);font-size:12px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)}\n.spec-toc-grid{margin-top:22px;display:grid;grid-template-columns:repeat(3,1fr);gap:34px 40px}\n.spec-toc-group b{display:block;font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--pitch)}\n.spec-toc-group ul{margin:13px 0 0;padding:0;list-style:none}\n.spec-toc-group li{padding:7px 0;font-size:13px;color:var(--ink);display:flex;justify-content:space-between;gap:12px;border-bottom:1px dashed var(--line)}\n.spec-toc-group li span{color:var(--ink3);font-size:10.5px;font-family:var(--mono)}\n.spec-note-band{padding:32px 64px;background:#FBF1DD;border-bottom:1px solid #d8b46a}\n.spec-note-band h3{margin:0;font-family:var(--mono);font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.12em;color:#8A5E12}\n.spec-note-band ol{margin:16px 0 0;padding-left:22px}\n.spec-note-band li{font-size:13px;line-height:1.7;margin-bottom:9px;color:#5c4413}\n.spec-note-band li b{color:#3d2d00}\n.section-divider{margin:64px 64px 0;padding-bottom:16px;border-bottom:2px solid var(--ink)}\n.section-divider small{display:block;font-family:var(--mono);font-size:11px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--pitch)}\n.section-divider h2{margin:10px 0 0;font-family:var(--display);font-weight:400;text-transform:uppercase;font-size:26px}\n.section-divider p{margin:8px 0 0;max-width:760px;font-size:13.5px;line-height:1.6;color:var(--ink3)}\n.frame-block{margin:44px 64px 0}\n.frame-caption{max-width:980px;margin-bottom:18px}\n.frame-caption .frame-index{display:inline-flex;align-items:center;gap:9px;font-family:var(--mono);font-size:11px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--pitch)}\n.frame-caption .frame-index code{font-family:var(--mono);font-size:11px;font-weight:500;padding:3px 9px;border-radius:20px;background:var(--mist);color:var(--pitch)}\n.frame-caption h3{margin:10px 0 0;font-size:19px;font-weight:700}\n.frame-caption p{margin:7px 0 0;font-size:13px;line-height:1.65;color:var(--ink3)}\n.frame-caption .frame-tags{margin-top:11px;display:flex;gap:7px;flex-wrap:wrap}\n.frame-caption .frame-tag{font-family:var(--mono);font-size:9.5px;font-weight:500;padding:5px 10px;border-radius:20px;background:#eef1ee;color:var(--ink3)}\n.frame-tray{background:#dbe2dc;border-radius:24px;padding:32px;display:inline-block}\n.frame-tray.mobile-tray{padding:24px 24px 36px}\n.frame-shell-wrap.desktop{width:1440px}\n.frame-shell-wrap.mobile{width:412px}\n\n/* ============================================================\n   APP SHELL -- sidebar + topbar (kept as a sound pattern, refined)\n   ============================================================ */\n.app-shell{background:var(--paper);border-radius:20px;box-shadow:var(--shadow-2);overflow:hidden}\n.app{display:grid;grid-template-columns:252px 1fr;min-height:900px}\n.rail-nav{background:var(--paper);border-right:1px solid var(--line);display:flex;flex-direction:column;padding:22px 14px}\n.rail-brand{padding:6px 10px 20px}\n.rail-search{display:flex;align-items:center;gap:9px;height:40px;padding:0 13px;border-radius:var(--r-pill);background:var(--mist);color:var(--ink4);font-size:12.5px;margin-bottom:14px}\n.rail-scroll{flex:1;overflow-y:auto}\n.rail-grp{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--ink4);padding:14px 10px 6px}\n.rail-item{display:flex;align-items:center;gap:11px;padding:9px 10px;border-radius:var(--r-sm);font-size:13px;font-weight:600;color:var(--ink2);cursor:pointer;position:relative}\n.rail-item.on{background:var(--ink);color:var(--volt)}\n.rail-item .badge{margin-left:auto;background:var(--red);color:#fff;font-size:9.5px;font-weight:700;padding:1px 6px;border-radius:999px}\n.rail-item.on .badge{background:var(--volt);color:var(--ink)}\n.rail-foot{margin-top:14px;padding-top:16px;border-top:1px solid var(--line);display:flex;align-items:center;gap:11px;padding-left:10px}\n.rail-foot .txt{min-width:0}\n.rail-foot b{display:block;font-size:12.5px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.rail-foot .role-txt{display:block;font-size:10.5px;color:var(--ink3);margin-top:1px}\n.main{display:flex;flex-direction:column;min-width:0}\n.top{display:flex;align-items:center;gap:14px;padding:22px 32px;border-bottom:1px solid var(--line)}\n.top .eyebrow{display:block;font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--pitch)}\n.top h1{margin:3px 0 0;font-size:21px;font-weight:800}\n.body{padding:28px 32px;flex:1;overflow:auto}\n.icon-btn{width:40px;height:40px;border-radius:999px;border:1.5px solid var(--line2);background:#fff;display:flex;align-items:center;justify-content:center;color:var(--ink);position:relative;flex:0 0 40px}\n.icon-btn u{position:absolute;top:-3px;right:-3px;background:var(--red);color:#fff;font:700 9.5px var(--mono);width:17px;height:17px;border-radius:999px;display:flex;align-items:center;justify-content:center;text-decoration:none}\n.avatar{width:38px;height:38px;border-radius:var(--r-pill);background:var(--pitch);color:var(--volt);font-family:var(--mono);font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;flex:0 0 38px}\n.avatar.lg{width:60px;height:60px;font-size:17px;flex:0 0 60px}\n\n/* ---- Mobile shell ---- */\n.scr{background:var(--paper);min-height:844px;display:flex;flex-direction:column;position:relative}\n.scr.rel{position:relative}\n.rel{position:relative}\n.ptop{display:flex;align-items:center;gap:12px;padding:16px 18px;border-bottom:1px solid var(--line)}\n.ptop h1{margin:0;font-size:16px;font-weight:800;flex:1}\n.pbody{padding:16px 18px 90px;flex:1;overflow:auto}\n.ptabs{display:flex;border-top:1px solid var(--line);background:#fff;padding:8px 6px 12px}\n.ptabs a{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;font-size:9.5px;font-weight:700;color:var(--ink3)}\n.ptabs a.on{color:var(--ink)}\n.actbar{display:flex;gap:10px;position:absolute;left:0;right:0;bottom:0;padding:14px 18px;background:#fff;border-top:1px solid var(--line)}\n\n/* ---- Shared bits ---- */\n.sp{flex:1}\n.flex{display:flex;align-items:center;gap:12px}\n.mut{color:var(--ink3)}\n.lbl{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--ink3)}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.m .two{grid-template-columns:1fr}\n\n.btn{display:inline-flex;align-items:center;gap:8px;height:44px;padding:0 20px;border-radius:var(--r-pill);border:1.5px solid transparent;font-size:13px;font-weight:700;white-space:nowrap;cursor:pointer;font-family:var(--sans);background:#fff}\n.btn.volt{background:var(--volt);color:var(--ink)}\n.btn.pitch{background:var(--pitch);color:#fff}\n.btn.outline{background:#fff;border-color:var(--line2);color:var(--ink)}\n.btn.danger{background:var(--red-t);color:var(--red);border-color:transparent}\n.btn.sm{height:36px;padding:0 15px;font-size:12px}\n.btn.full{width:100%;justify-content:center}\n\n.pill{display:inline-flex;align-items:center;font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:4px 10px;border-radius:999px}\n.pill.g{background:var(--pitch-t);color:var(--pitch)}\n.pill.a{background:var(--amber-t);color:var(--amber)}\n.pill.r{background:var(--red-t);color:var(--red)}\n.pill.n{background:var(--mist);color:var(--ink3)}\n\n.card{background:#fff;border-radius:var(--r-lg);box-shadow:var(--shadow-1)}\n.card-h{display:flex;align-items:center;gap:10px;padding:18px 22px;border-bottom:1px solid var(--line)}\n.card-h h3{margin:0;font-size:14.5px;font-weight:800}\n.card-h .hint{font-size:11px;color:var(--ink3)}\n.card-b{padding:20px 22px}\n\n.list-row{display:flex;align-items:center;gap:13px;padding:13px 0;border-bottom:1px solid var(--line);cursor:pointer}\n.list-row:last-child{border-bottom:0}\n.who{flex:1;min-width:0}\n.who b{display:block;font-size:13px;font-weight:700}\n.who span:not(.avatar){display:block;font-size:11.5px;color:var(--ink3);margin-top:2px}\n.chev{color:var(--ink4)}\n\n.field{margin-bottom:16px}\n.field label{display:flex;justify-content:space-between;font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--ink3);margin-bottom:7px}\n.field label em{font-style:normal;color:var(--ink4);font-weight:500}\n.in{width:100%;height:46px;border:1.5px solid var(--line2);border-radius:var(--r-sm);padding:0 14px;font:inherit;font-size:13.5px;background:#fff}\ntextarea.in{min-height:90px;padding:11px 14px}\nselect.in{appearance:none;padding-right:36px;background-image:url('data:image/svg+xml;utf8,<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"%2371847A\" stroke-width=\"2\"><path d=\"M2 5l5 5 5-5\"/></svg>');background-repeat:no-repeat;background-position:right 14px center}\n\n.callout{border-radius:var(--r-md);padding:15px 18px;font-size:12.5px;line-height:1.6;display:flex;gap:10px}\n.callout.g{background:var(--pitch-t);color:var(--pitch-d)}\n.callout.a{background:var(--amber-t);color:#7A5A0E}\n\n.bar-track{height:9px;background:var(--mist);border-radius:999px;overflow:hidden}\n.bar-track i{display:block;height:100%;border-radius:999px}\n\n.stepper{display:flex;align-items:center;margin-bottom:28px}\n.stepper .sp-i{display:flex;align-items:center;gap:9px}\n.stepper .sp-i b{width:26px;height:26px;border-radius:999px;background:var(--mist);color:var(--ink3);font:700 11px var(--mono);display:flex;align-items:center;justify-content:center}\n.stepper .sp-i.on b{background:var(--ink);color:var(--volt)}\n.stepper .sp-i.dn b{background:var(--pitch);color:#fff}\n.stepper .sp-i span{font-size:12px;font-weight:700;color:var(--ink3)}\n.stepper .sp-i.on span,.stepper .sp-i.dn span{color:var(--ink)}\n.stepper .ln{flex:1;height:1.5px;background:var(--line);margin:0 12px}\n.m .stepper .sp-i span{display:none}\n\n/* ============================================================\n   NEW: bento grid (varied cell sizes, not uniform KPI rows)\n   ============================================================ */\n.bento{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px}\n.m .bento{grid-template-columns:1fr 1fr}\n.bento-cell{background:#fff;border-radius:var(--r-lg);box-shadow:var(--shadow-1);padding:20px}\n.bento-cell.dark{background:linear-gradient(145deg,var(--coal),var(--coal2));color:#fff}\n.bento-cell .lbl{margin-bottom:8px}\n.bento-cell .dark .lbl{color:rgba(255,255,255,.55)}\n.bento-cell strong{display:block;font-family:var(--display);font-weight:400;font-size:34px;line-height:1}\n.bento-cell.dark strong{color:var(--volt)}\n.bento-cell small{display:block;margin-top:6px;font-size:11px;color:var(--ink3)}\n.bento-cell.dark small{color:rgba(255,255,255,.62)}\n\n/* ============================================================\n   NEW: quicklinks row (focused, 4 items, not 8)\n   ============================================================ */\n.qlink-row{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}\n.m .qlink-row{grid-template-columns:1fr 1fr}\n.qlink{background:#fff;border-radius:var(--r-lg);box-shadow:var(--shadow-1);padding:20px;text-align:left;border:none;font:inherit;cursor:pointer;display:flex;flex-direction:column;gap:0}\n.qlink .ic{width:38px;height:38px;border-radius:var(--r-sm);background:var(--mist);color:var(--pitch);display:flex;align-items:center;justify-content:center;margin-bottom:12px;font-weight:900}\n.qlink b{font-size:13.5px;font-weight:800}\n.qlink small{margin-top:5px;font-size:11px;color:var(--ink3);line-height:1.4}\n.qlink .go{margin-top:12px;font-family:var(--mono);font-size:10.5px;font-weight:700;color:var(--pitch)}\n\n/* ============================================================\n   NEW: usage-remaining strip (compact multi-metric, not big bars)\n   ============================================================ */\n.usage-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:0}\n.m .usage-strip{grid-template-columns:1fr 1fr}\n.usage-strip-item{padding:16px 20px;border-right:1px solid var(--line)}\n.usage-strip-item .lbl{display:block;margin-bottom:9px}\n.m .usage-strip-item:nth-child(2n){border-right:0}\n.usage-strip-item:last-child{border-right:0}\n.usage-strip-item strong{font-family:var(--display);font-weight:400;font-size:26px}\n.usage-strip-item small{display:block;font-size:10.5px;color:var(--ink3);margin-top:2px}\n.usage-strip-item .bar-track{margin-top:9px;height:5px}\n\n/* ============================================================\n   NEW: profile hero (dark gradient, score tiles) -- replaces the\n   plain white card + small ring used before.\n   ============================================================ */\n.profile-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:20px;padding:26px;border-radius:var(--r-lg);background:linear-gradient(145deg,var(--coal),var(--coal2));color:#fff;position:relative;overflow:hidden}\n.m .profile-hero{grid-template-columns:1fr}\n.profile-hero .hero-name{display:flex;align-items:center;gap:15px}\n.profile-hero h2{margin:0;font-size:22px}\n.profile-hero p{margin:5px 0 0;font-size:12px;color:rgba(255,255,255,.66)}\n.profile-hero .chips{display:flex;gap:8px;margin-top:11px;flex-wrap:wrap}\n.hero-scores{display:flex;gap:10px;flex-wrap:wrap}\n.m .hero-scores{margin-top:16px}\n.score-tile{min-width:90px;padding:12px 15px;border-radius:14px;background:rgba(255,255,255,.09);text-align:center}\n.score-tile strong{display:block;font-family:var(--display);font-weight:400;font-size:26px;color:var(--volt)}\n.score-tile span{display:block;font-family:var(--mono);font-size:8.5px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:rgba(255,255,255,.58);margin-top:3px}\n.profile-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}\n.profile-actions .btn.outline{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.2);color:#fff}\n.hero-action-pills{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}\n.hero-pill{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 13px;border-radius:999px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);color:#fff;font-size:11px;font-weight:700;font-family:inherit}\n\n/* ============================================================\n   NEW: compatibility visualisation -- score + labelled bars\n   ============================================================ */\n.compat-viz{display:grid;grid-template-columns:170px minmax(0,1fr);gap:22px;align-items:center}\n.m .compat-viz{grid-template-columns:1fr}\n.compat-score{text-align:center;padding:20px;border-radius:var(--r-md);background:var(--mist)}\n.compat-score strong{display:block;font-family:var(--display);font-weight:400;font-size:44px;color:var(--pitch)}\n.compat-score span{font-family:var(--mono);font-size:9.5px;font-weight:700;color:var(--ink3);text-transform:uppercase}\n.breakdown-bars{display:grid;gap:11px}\n.breakdown-row{display:grid;grid-template-columns:150px minmax(0,1fr) 38px;gap:11px;align-items:center}\n.m .breakdown-row{grid-template-columns:112px minmax(0,1fr) 32px}\n.breakdown-row label{font-size:11px;font-weight:700}\n.breakdown-row .track{height:8px;background:var(--mist);border-radius:999px;overflow:hidden}\n.breakdown-row .track i{display:block;height:100%;background:var(--pitch);border-radius:999px}\n.breakdown-row strong{font-family:var(--mono);font-size:10px;font-weight:700;text-align:right}\n\n/* ============================================================\n   NEW: multi-select chip pickers (compatibility setup, real\n   mechanism instead of free text)\n   ============================================================ */\n.chip-picker{display:flex;flex-wrap:wrap;gap:8px}\n.chip-option{display:inline-flex;align-items:center;gap:7px;padding:9px 14px;border-radius:999px;border:1.5px solid var(--line2);background:#fff;font-size:12px;font-weight:600;color:var(--ink2);cursor:pointer;font-family:inherit}\n.chip-option .ck{width:15px;height:15px;border-radius:4px;border:1.5px solid var(--line2);display:flex;align-items:center;justify-content:center;font-size:9px;flex:0 0 15px}\n.chip-option.on{background:var(--mist);border-color:var(--pitch);color:var(--ink)}\n.chip-option.on .ck{background:var(--pitch);border-color:var(--pitch);color:#fff}\n\n/* ============================================================\n   NEW: dark wizard chrome -- visually distinct focused mode\n   ============================================================ */\n.wizard-shell{background:var(--canvas);min-height:900px;display:flex;flex-direction:column}\n.wizard-top{display:flex;align-items:center;gap:14px;padding:20px 32px;background:var(--coal);color:#fff}\n.m .wizard-top{padding:15px 18px}\n.wizard-brand{font:700 11px var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--volt)}\n.wizard-top .wtitle{font-weight:800;font-size:14.5px;margin-top:2px}\n.wizard-top .meta{font:600 10px var(--mono);color:rgba(255,255,255,.55)}\n.wizard-close{height:38px;padding:0 16px;border-radius:999px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.06);color:#fff;display:flex;align-items:center;gap:7px;font-size:12px;font-weight:700;cursor:pointer}\n.wizard-body{flex:1;padding:40px;display:flex;justify-content:center}\n.m .wizard-body{padding:22px 18px}\n\n/* ============================================================\n   Rankings / pipeline / prediction cards / fixtures / chat --\n   distinct per-content-type treatments instead of one shared row\n   ============================================================ */\n.rank-row{display:grid;grid-template-columns:44px 1fr auto auto;gap:14px;align-items:center;padding:13px 0;border-bottom:1px solid var(--line)}\n.rank-row:last-child{border-bottom:0}\n.rank-num{width:34px;height:34px;border-radius:var(--r-sm);background:var(--mist);color:var(--pitch);font-family:var(--display);font-weight:400;font-size:14px;display:flex;align-items:center;justify-content:center}\n.rank-num.n1{background:var(--ink);color:var(--volt)}\n\n.pred-type-card{display:flex;flex-direction:column;align-items:flex-start;background:#fff;border:1.5px solid var(--line2);border-radius:var(--r-md);padding:18px;cursor:pointer;font:inherit;color:inherit;text-align:left}\n.pred-type-card .ic{width:38px;height:38px;border-radius:var(--r-sm);background:var(--mist);color:var(--pitch);display:flex;align-items:center;justify-content:center;margin-bottom:12px}\n.pred-type-card b{font-size:13px;font-weight:800}\n.pred-type-card small{margin-top:6px;color:var(--ink3);font-size:11px;line-height:1.5}\n.pred-type-card.on{border-color:var(--ink);background:var(--mist)}\n.pred-type-card.on .ic{background:var(--ink);color:var(--volt)}\n\n.role-gate{border:1.5px dashed var(--line2);border-radius:var(--r-md);padding:22px;text-align:center}\n.role-gate b{display:block;font-size:13px;margin-bottom:8px}\n.role-gate p{margin:0;font-size:12px;color:var(--ink3)}\n\n.pack-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}\n.m .pack-grid{grid-template-columns:repeat(2,1fr)}\n.pack-card{border:1.5px solid var(--line2);border-radius:var(--r-md);padding:16px 12px;background:#fff;text-align:center;cursor:pointer;font:inherit}\n.pack-card b{display:block;font-family:var(--display);font-weight:400;font-size:22px}\n.pack-card span{display:block;font-size:10.5px;color:var(--ink3);margin-top:2px}\n.pack-card strong{display:block;font-size:13px;margin-top:8px;color:var(--pitch)}\n.pack-card.on{border-color:var(--ink);background:var(--mist)}\n.seg{display:inline-flex;background:var(--mist);border-radius:999px;padding:3px;gap:2px}\n.seg a{padding:8px 15px;border-radius:999px;font-size:12px;font-weight:700;color:var(--ink3);cursor:pointer}\n.seg a.on{background:#fff;color:var(--ink);box-shadow:var(--shadow-1)}\n\n.filter-row{display:flex;gap:8px;flex-wrap:wrap}\n.filter-chip{height:34px;padding:0 15px;border-radius:999px;border:1.5px solid var(--line2);background:#fff;font-size:11.5px;font-weight:700;color:var(--ink2);font-family:inherit}\n.filter-chip.on{background:var(--ink);border-color:var(--ink);color:var(--volt)}\n\n.thread-row{display:grid;grid-template-columns:38px minmax(0,1fr) auto;gap:10px;padding:13px 14px;border-bottom:1px solid var(--line);cursor:pointer;align-items:start}\n.thread-row.on{background:#F0F6F2}\n.thread-row .avatar{width:38px;height:38px}\n.thread-row .tx{flex:1;min-width:0}\n.thread-row .tx b{font-size:13px;font-weight:700;display:block}\n.thread-row .tx .org{font-family:var(--mono);font-size:10px;color:var(--pitch);margin-top:2px}\n.thread-row .tx .pv{font-size:11px;color:var(--ink3);margin:4px 0 0;line-height:1.4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.thread-row .tm{font:700 9px var(--mono);color:var(--ink3)}\n.msg-list-head{padding:14px;border-bottom:1px solid var(--line)}\n.msg-list-panel{border-right:1px solid var(--line);background:#FBFCFB;border-radius:var(--r-lg) 0 0 var(--r-lg);overflow:hidden}\n.msg-bubble{max-width:64%;padding:12px 15px;border-radius:16px;font-size:12.5px;line-height:1.55}\n.msg-bubble.in{background:var(--mist);border-radius:16px 16px 16px 4px}\n.msg-bubble.out{margin-left:auto;background:var(--ink);color:#fff;border-radius:16px 16px 4px 16px}\n\n.radar-bubble{max-width:78%;padding:12px 15px;border-radius:16px;margin-top:10px;font-size:12.5px;line-height:1.55}\n.radar-bubble.ai{background:var(--mist);border-radius:16px 16px 16px 4px}\n.radar-bubble.user{margin-left:auto;background:var(--ink);color:#fff;border-radius:16px 16px 4px 16px}\n\n.cal-head{display:grid;grid-template-columns:repeat(7,1fr);background:var(--canvas);border-bottom:1px solid var(--line)}\n.cal-head span{padding:10px;font-family:var(--mono);font-size:10px;text-transform:uppercase;color:var(--ink3);text-align:center}\n.cal-grid{display:grid;grid-template-columns:repeat(7,1fr)}\n.cal-day{min-height:88px;padding:8px;border:1px solid var(--line)}\n.cal-day.today{background:var(--pitch-t)}\n.cal-day>b{font-family:var(--mono);font-size:10.5px;color:var(--ink3)}\n.cal-event{margin-top:6px;padding:5px 7px;border-radius:6px;background:var(--pitch-t);border-left:3px solid var(--pitch)}\n.cal-event.priority{background:var(--amber-t);border-left-color:var(--amber)}\n.cal-event b{display:block;font-size:10px}\n.cal-event span{display:block;font-size:9px;color:var(--ink3)}\n.dateplate{width:44px;text-align:center;background:var(--mist);border-radius:var(--r-sm);padding:6px 0;flex:0 0 44px}\n.dateplate.g{background:var(--pitch-t)}\n.dateplate b{display:block;font-family:var(--display);font-weight:400;font-size:16px}\n.dateplate span{display:block;font-family:var(--mono);font-size:8px;color:var(--ink3)}\n\n/* ---- Scout Setup: real option cards with checkbox + description ---- */\n.setup-opt-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.m .setup-opt-grid{grid-template-columns:1fr}\n.setup-opt{display:flex;gap:10px;padding:13px;border:1.5px solid var(--line2);border-radius:var(--r-md);background:#fff}\n.setup-opt.on{border-color:var(--pitch);background:var(--pitch-t)}\n.setup-opt .check{width:20px;height:20px;border-radius:6px;border:1.5px solid var(--line2);display:flex;align-items:center;justify-content:center;flex:0 0 20px;font-size:11px;margin-top:1px}\n.setup-opt.on .check{background:var(--pitch);border-color:var(--pitch);color:#fff}\n.setup-opt b{display:block;font-size:12.5px}\n.setup-opt small{display:block;color:var(--ink3);font-size:11px;line-height:1.4;margin-top:3px}\n.setup-warning{display:flex;gap:10px;padding:14px 16px;border:1px solid var(--line2);border-radius:14px;background:var(--mist);font-size:11.5px;line-height:1.5;color:var(--ink2);margin-bottom:20px}\n.setup-warning b{color:var(--ink)}\n\n/* ---- Ask Radar: distinct bold-green identity, not another white-card page ---- */\n.radar-shell{background:linear-gradient(160deg,var(--coal) 0%,var(--coal2) 55%,#0d3327 100%);border-radius:var(--r-lg);padding:22px;color:#fff;display:flex;flex-direction:column;min-height:460px}\n.radar-shell-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}\n.radar-avatar{width:34px;height:34px;border-radius:999px;background:var(--volt);color:var(--ink);display:flex;align-items:center;justify-content:center;flex:0 0 34px}\n.radar-shell .radar-bubble.ai{background:rgba(255,255,255,.1);color:#fff;border-radius:16px 16px 16px 4px}\n.radar-shell .radar-bubble.user{background:var(--volt);color:var(--ink);border-radius:16px 16px 4px 16px}\n.radar-quick-chip{height:34px;padding:0 15px;border-radius:999px;border:1.5px solid rgba(255,255,255,.25);background:rgba(255,255,255,.06);font-size:11.5px;font-weight:700;color:#fff;font-family:inherit}\n.radar-input-row{display:flex;gap:10px;margin-top:14px}\n.radar-input-row input{flex:1;height:46px;border-radius:999px;border:1.5px solid rgba(255,255,255,.2);background:rgba(255,255,255,.08);color:#fff;padding:0 18px;font:inherit;font-size:13px}\n.radar-input-row input::placeholder{color:rgba(255,255,255,.5)}\n.radar-limit-strip{background:linear-gradient(135deg,var(--coal),var(--coal2));border-radius:var(--r-lg);padding:18px 22px;color:#fff}\n.radar-limit-strip strong{font-family:var(--display);font-weight:400;font-size:24px;color:var(--volt)}\n.sl-logo-mark{background-repeat:no-repeat;background-position:left center;background-size:contain;display:block}.sl-logo-mark.white{background-image:url(data:image/png;base64,)}.sl-logo-mark.colour{background-image:url(data:image/png;base64,)}";

